import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
  const [isOpen, setIsOpen] = useState(false);
    
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <>
      <div className="font-poppins text-gray-700   w-full  top-0 left-0">
        <div className=" lg:flex bg-gray-300  items-center justify-between lg:px-16">
          <div className=" items-start ">
            <Link to="/">
              <img
                src="/img/navLogo1.png"
                alt="Navbar Logo"
                className=" h-20 "
              />
            </Link>
          </div>
          <p className=" absolute top-6 right-6 lg:hidden text-3xl" onClick={()=>{setOpne(!open);}}>
            
          <i class={!open?"bi bi-list":"bi bi-x"}></i>
          </p>
        <ul className={`lg:flex absolute lg:static md:mt-0 z-auto z[-1] lg:opacity-100 w-full
           p-4 md:p-0 md:w-auto md:pt-2 md:me-12 bg-gray-300 pl-10   ${open?"mt-0 opacity-100  transition-all duration-300 ease-in ":"mt-[-350px] opacity-0 "} `} >
            {
              // absolute md:relative sm:w-full md:w-auto   md:flex md:items-center sm:ms-0 
                links.map((link)=>{

                  return  <li key={link.name} className="   md:ml-8 mb-3  text-lg hover:border-b border-purple-500 md:pt-2 ">
                    <Link to={link.to}>{link.name}</Link>
                    </li>
                })
            }
            <button className=" bg-purple-500 hover:bg-purple-700  hover:text-white rounded-lg w-20 h-10 md:ms-8" >Login</button>
          </ul>
        </div>
      </div>
    </>
  );
}

export default NavBar;
